from typing import Literal

from fastapi import FastAPI, Query, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ConfigDict, Field, SecretStr

from .reader import Reader, ReaderFault, Settings, USERNAME
from .cursors import valid_inbox_cursor
import hmac


class Login(BaseModel):
    model_config = ConfigDict(extra="forbid")
    username: str = Field(default=USERNAME, max_length=50)
    password: SecretStr = Field(min_length=1, max_length=1000)
    verification_code: str = Field(default="", pattern=r"^[0-9 ]{0,12}$")


class ContinueLogin(BaseModel):
    model_config = ConfigDict(extra="forbid")
    verification_code: str = Field(default="", pattern=r"^[0-9 ]{0,12}$")


def create_app(settings: Settings, reader=None):
    app = FastAPI(docs_url=None, redoc_url=None, openapi_url=None)
    engine = reader or Reader(settings)

    @app.middleware("http")
    async def protect(request: Request, call_next):
        auth = request.headers.get("authorization", "")
        if not hmac.compare_digest(auth, "Bearer " + settings.token):
            return JSONResponse({"error": "unauthorized", "message": "Reader service authorization required."}, 401)
        try:
            size = int(request.headers.get("content-length", "0"))
        except ValueError:
            size = 10001
        if size > 8192:
            return JSONResponse({"error": "body_too_large", "message": "Request too large."}, 413)
        if request.method == "POST":
            # Check the actual bytes too, so chunked uploads cannot bypass the limit.
            chunks, total = [], 0
            async for chunk in request.stream():
                total += len(chunk)
                if total > 8192:
                    return JSONResponse({"error": "body_too_large", "message": "Request too large."}, 413)
                chunks.append(chunk)
            request._body = b"".join(chunks)
        response = await call_next(request)
        response.headers["Cache-Control"] = "no-store"
        response.headers["X-Content-Type-Options"] = "nosniff"
        return response

    @app.exception_handler(ReaderFault)
    async def reader_fault(request, exc):
        return JSONResponse({"error": exc.code, "message": exc.message}, exc.status)

    @app.exception_handler(RequestValidationError)
    async def invalid_request(request, exc):
        # FastAPI's default response can echo rejected password input.
        return JSONResponse({"error": "invalid_request", "message": "Check the request fields."}, 422)

    @app.exception_handler(Exception)
    async def failure(request, exc):
        return JSONResponse({"error": "reader_unavailable", "message": "The reader service could not complete this request."}, 503)

    @app.get("/v1/status")
    def status():
        return engine.status()

    @app.post("/v1/connect")
    def connect(payload: Login):
        return engine.connect(payload.username, payload.password.get_secret_value(), payload.verification_code)

    @app.post("/v1/continue")
    def continue_connection(payload: ContinueLogin):
        return engine.continue_connection(payload.verification_code)

    @app.get("/v1/conversations")
    def conversations(folder: Literal["primary", "general", "requests", "hidden"] = "primary", limit: int = Query(20, ge=1, le=50), after: str = Query("", max_length=2000)):
        if not valid_inbox_cursor(after):
            raise ReaderFault("invalid_request", "Use next_after from the preceding inbox result.", 422)
        return engine.conversations(folder, limit, after)

    @app.get("/v1/conversations/{thread_id}/messages")
    def messages(thread_id: str, limit: int = Query(50, ge=1, le=50), after: str = Query("", max_length=2000, pattern=r"^[A-Za-z0-9_+=/.,:;-]*$")):
        return engine.messages(thread_id, limit, after)

    @app.get("/v1/conversations/{thread_id}/voice/{message_id}")
    def voice(thread_id: str, message_id: str, after: str = Query("", max_length=2000, pattern=r"^[A-Za-z0-9_+=/.,:;-]*$")):
        return engine.voice(thread_id, message_id, after)

    return app

