"""Validate inbox cursors without rewriting Instagram's opaque value."""
import json
import re


def valid_inbox_cursor(value):
    if not isinstance(value, str) or len(value) > 2000:
        return False
    if not value or re.fullmatch(r"[A-Za-z0-9_+=/.,:;-]+", value):
        return True
    try:
        cursor = json.loads(value)
    except (ValueError, TypeError):
        return False
    keys = {"cursor_thread_v2_id", "cursor_relevancy_score", "cursor_timestamp_seconds"}
    return (isinstance(cursor, dict) and set(cursor) == keys
            and all(type(v) is int and 0 <= v <= 9007199254740991 for v in cursor.values()))

