"""Single-account Instagram reader. No inbox database and no sending API."""
from __future__ import annotations

import json
import logging
import os
import re
import threading
import time
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urlsplit

from cryptography.fernet import Fernet
from instagrapi import Client
from .verification import LoginVerification

USERNAME = "jessemcinnes_"
READ_PATH = re.compile(r"^(?:accounts/current_user/|direct_v2/(?:inbox/|pending_inbox/|spam_inbox/|threads/[0-9]+/))$")
ID = re.compile(r"^[0-9]{1,100}$")
CURSOR = re.compile(r"^[A-Za-z0-9_+=/.,:;-]{1,2000}$")
VERIFICATION_MESSAGES = {
    "approval": ("instagram_approval_pending", "Open Instagram and approve this login. Return here and tap Check approval. No code is needed for this step."),
    "totp": ("authenticator_code_required", "Instagram is asking for a code from your authenticator app. It has not requested a text message."),
    "sms": ("sms_code_required", "Instagram selected text-message verification. Enter the code if it arrives."),
    "backup_codes": ("backup_code_required", "Instagram selected backup-code verification. Enter one of your saved Instagram backup codes."),
}


class ReaderFault(Exception):
    def __init__(self, code, message, status=400):
        super().__init__(message)
        self.code, self.message, self.status = code, message, status


@dataclass(frozen=True)
class Settings:
    token: str
    encryption_key: str
    session_path: Path

    @classmethod
    def from_env(cls):
        token = os.environ.get("IG_BRIDGE_TOKEN", "")
        key = os.environ.get("IG_SESSION_ENCRYPTION_KEY", "")
        if len(token) < 40:
            raise RuntimeError("IG_BRIDGE_TOKEN must contain at least 40 characters.")
        Fernet(key.encode())
        return cls(token, key, Path(os.environ.get("IG_SESSION_PATH", "/data/instagram-session.enc")))


class ReadOnlyClient(Client):
    """Authentication is explicit. Afterwards, only bounded inbox GETs are allowed."""
    authenticating = False

    def __init__(self):
        # instagrapi calls this a timeout, but uses it as a sleep BEFORE requests.
        # Twenty seconds here made account verification + voice lookup exceed
        # the connector's response window before transcription could finish.
        super().__init__(request_timeout=1, with_challenge_flow=False)
        self.logger = logging.getLogger("instagram_reader.silent")
        self.logger.disabled = True
        self.request_logger = self.logger
        self.session_retry_total = 0
        self.public_request_retries_count = 0

    def set_settings(self, settings):
        # Previously saved sessions contain the old 20-second pause. Keep their
        # device identity and authentication while correcting that delay.
        settings = dict(settings)
        settings["request_timeout"] = 1
        settings["session_retry_total"] = 0
        settings["public_request_retries_count"] = 0
        return super().set_settings(settings)

    def login_flow(self):
        # The stock flow also retrieves unrelated feeds. This reader needs only DMs.
        return True

    def private_request(self, endpoint, data=None, params=None, **kwargs):
        path = urlsplit(endpoint)
        domain = kwargs.get("domain")
        # Current instagrapi CAA sign-in uses this official alternate API host.
        # Permit it only during explicit authentication, never for inbox reads.
        auth_domain = self.authenticating and domain in ("i.instagram.com", "b.i.instagram.com")
        if path.scheme or path.netloc or (domain and not auth_domain):
            raise ReaderFault("read_only", "Custom Instagram hosts are not allowed.")
        allowed = bool(READ_PATH.fullmatch(path.path)) and data is None
        if path.path.startswith("direct_v2/") and not allowed:
            raise ReaderFault("read_only", "This reader cannot change Instagram messages.")
        if not self.authenticating and not allowed:
            raise ReaderFault("read_only", "Only Instagram inbox read requests are allowed.")
        return super().private_request(endpoint, data=data, params=params, **kwargs)


def safe_url(value):
    if not isinstance(value, str) or len(value) > 12000:
        return None
    try:
        u = urlsplit(value)
        host = (u.hostname or "").lower()
        valid_host = any(host == x or host.endswith("." + x) for x in ("cdninstagram.com", "fbcdn.net", "fbsbx.com"))
        if u.scheme == "https" and valid_host and not u.username and not u.password and not u.port and not u.fragment and "access_token=" not in u.query:
            return value
    except ValueError:
        pass
    return None


def timestamp(value):
    try:
        return datetime.fromtimestamp(int(value) / 1_000_000, timezone.utc).isoformat()
    except (TypeError, ValueError, OverflowError, OSError):
        return None


def person(user):
    return {"id": str(user.get("pk", "")), "username": user.get("username"), "name": user.get("full_name")}


def attachment_records(item):
    result = []
    if item.get("item_type") == "voice_media" or item.get("voice_media"):
        voice = item.get("voice_media") or {}
        media = voice.get("media") or {}
        audio = media.get("audio") or {}
        result.append({"type": "audio", "url": safe_url(audio.get("audio_src")), "duration_ms": audio.get("duration")})
    media = item.get("media") or item.get("visual_media", {}).get("media") or {}
    if isinstance(media, dict):
        videos = media.get("video_versions") or []
        images = (media.get("image_versions2") or {}).get("candidates") or []
        if videos:
            result.append({"type": "video", "url": safe_url(videos[0].get("url"))})
        elif images:
            result.append({"type": "image", "url": safe_url(images[0].get("url"))})
    return result[:10]


def message_record(item, users, viewer_id, after):
    sender = str(item.get("user_id", ""))
    kind = item.get("item_type", "unknown")
    body = item.get("text")
    if body is None and isinstance(item.get("link"), dict):
        body = item["link"].get("text")
    attachments = attachment_records(item)
    return {
        "id": str(item.get("item_id", "")), "created_time": timestamp(item.get("timestamp")),
        "from": users.get(sender, {"id": sender}), "direction": "outgoing" if sender == str(viewer_id) else "incoming",
        "text": body if isinstance(body, str) else None, "has_text": bool(body), "item_type": kind,
        "attachments": attachments, "message_page_after": after or None,
        "content_available": bool(body or any(a.get("url") for a in attachments)),
        "content_note": None if body or attachments else "This message type has no readable text or downloadable media in the response.",
    }


def page_info(value):
    cursor = value.get("oldest_cursor")
    more = value.get("has_older", bool(cursor))
    if more and not cursor:
        return {"has_more": True, "next_after": None, "pagination_error": "Instagram indicated more history but omitted its cursor."}
    return {"has_more": bool(more and cursor), "next_after": cursor if more else None}


class Reader:
    def __init__(self, settings, factory=ReadOnlyClient, clock=time.monotonic, sleep=time.sleep):
        self.settings, self.factory, self.clock, self.sleep = settings, factory, clock, sleep
        self.cipher = Fernet(settings.encryption_key.encode())
        self.lock = threading.RLock()
        self.client = None
        self.verified_at = 0
        self.last_read = -100
        self.next_login = 0
        self.cooldown_until = 0
        self.invalid_session = False
        self.pending = None
        self.pending_until = 0
        self.next_check = 0
        self.last_connection_fault = None

    def _fault(self, error):
        if isinstance(error, ReaderFault):
            return error
        kind = type(error).__name__
        if kind in ("TwoFactorRequired", "InvalidTwoFactorCode"):
            return ReaderFault("verification_code_rejected", "Instagram did not accept that verification code. Check the selected method and try again.", 409)
        if kind == "VerificationUnavailable":
            return ReaderFault("verification_unavailable", "Instagram returned a verification step this reader could not continue. A text message has not been confirmed. The connector needs attention.", 409)
        if "Challenge" in kind or "Checkpoint" in kind or "Consent" in kind:
            return ReaderFault("instagram_approval_required", "Instagram needs you to approve this login in its own app. Open Instagram, complete the check, then reconnect.", 409)
        if kind in ("LoginRequired", "ClientLoginRequired"):
            self.client, self.invalid_session = None, True
            return ReaderFault("login_required", "Your private Instagram session expired. Reconnect from the reader page.", 409)
        if kind in ("BadPassword", "BadCredentials"):
            return ReaderFault("login_rejected", "Instagram rejected the sign-in. Check your password in Instagram before retrying.", 409)
        if kind in ("PleaseWaitFewMinutes", "RateLimitError", "FeedbackRequired", "ClientThrottledError"):
            self.cooldown_until = self.clock() + 300
            return ReaderFault("instagram_rate_limit", "Instagram asked this reader to pause. Wait at least five minutes before trying again.", 429)
        if kind in ("ClientNotFoundError", "DirectThreadNotFound"):
            return ReaderFault("not_found", "Instagram did not return this conversation.", 404)
        return ReaderFault("instagram_read_failed", "Instagram could not complete this request. No messages were changed.", 502)

    def _persist(self):
        path = self.settings.session_path
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        data = self.client.get_settings()
        data.pop("password", None)
        payload = self.cipher.encrypt(json.dumps({"username": USERNAME, "settings": data}).encode())
        temp = path.with_suffix(".tmp")
        fd = os.open(temp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "wb") as stream:
            stream.write(payload)
        os.chmod(temp, 0o600)
        os.replace(temp, path)

    def _load(self):
        if self.client or self.invalid_session or not self.settings.session_path.exists():
            return
        try:
            data = json.loads(self.cipher.decrypt(self.settings.session_path.read_bytes()))
            if data["username"] != USERNAME:
                raise ValueError("Unexpected account")
            client = self.factory()
            client.set_settings(data["settings"])
            client.username = USERNAME
            self.client = client
        except Exception:
            self.invalid_session = True
            raise ReaderFault("session_unavailable", "The saved Instagram session cannot be opened. Reconnect from the reader page.", 409)

    def _verify(self, force=False):
        if self.clock() < self.cooldown_until:
            raise ReaderFault("instagram_rate_limit", "Instagram asked this reader to pause. Wait at least five minutes.", 429)
        self._load()
        if not self.client:
            raise ReaderFault("login_required", "Connect Instagram from the private reader page first.", 409)
        if force or self.clock() - self.verified_at > 60 or not self.verified_at:
            user = self.client.private_request("accounts/current_user/", params={"edit": "true"}).get("user", {})
            if str(user.get("username", "")).lower() != USERNAME:
                self.client, self.invalid_session = None, True
                raise ReaderFault("wrong_account", "This reader only accepts @jessemcinnes_.", 403)
            self.verified_at = self.clock()
        return self.client

    def status(self):
        with self.lock:
            try:
                if self.pending:
                    self._pending_active()
                    return self._pending_status()
                if not self.client and self.last_connection_fault:
                    raise self.last_connection_fault
                self._verify()
                return {"connected": True, "username": USERNAME, "read_only": True, "provider": "instagrapi", "inbox_archived": False}
            except Exception as exc:
                fault = self._fault(exc)
                return {"connected": False, "username": USERNAME, "read_only": True, "provider": "instagrapi", "code": fault.code, "message": fault.message}

    def _pending_active(self):
        if self.pending and self.clock() >= self.pending_until:
            self.pending = None
            self.last_connection_fault = ReaderFault("verification_expired", "This login request expired. Start a new sign-in from this page.", 409)
        if not self.pending:
            raise self.last_connection_fault or ReaderFault("login_required", "Start a sign-in from this page first.", 409)
        if self.clock() < self.cooldown_until:
            raise ReaderFault("instagram_rate_limit", "Instagram asked this reader to pause. Wait at least five minutes.", 429)

    def _pending_status(self):
        code, message = VERIFICATION_MESSAGES[self.pending.kind]
        return {"connected": False, "username": USERNAME, "read_only": True, "provider": "instagrapi", "code": code, "message": message,
                "verification": self.pending.kind, "expires_in": max(0, int(self.pending_until - self.clock())), "retry_after": max(0, int(self.next_check - self.clock() + 0.999))}

    def _finish_connection(self, candidate):
        candidate.authenticating = False
        user = candidate.private_request("accounts/current_user/", params={"edit": "true"}).get("user", {})
        if str(user.get("username", "")).lower() != USERNAME:
            raise ReaderFault("wrong_account", "Instagram returned a different account. The session was not saved.", 403)
        self.client = candidate
        self.invalid_session = False
        self.verified_at = self.clock()
        self._persist()
        self.pending = None
        self.last_connection_fault = None
        return {"connected": True, "username": USERNAME, "read_only": True, "provider": "instagrapi"}

    def continue_connection(self, verification_code=""):
        with self.lock:
            if not self.pending and self.client:
                self._verify()
                return self.status()
            self._pending_active()
            if self.clock() < self.next_check:
                return self._pending_status()
            code = verification_code.replace(" ", "")
            if self.pending.kind != "approval" and not re.fullmatch(r"[0-9]{6}|[0-9]{8}", code):
                return self._pending_status()
            self.next_check = self.clock() + 8
            candidate = self.pending.client
            try:
                candidate.authenticating = True
                if self.pending.check(code):
                    return self._finish_connection(candidate)
                if self.pending.kind != "approval":
                    raise ReaderFault("verification_code_rejected", "Instagram did not confirm that code. Check it and try again.", 409)
                return self._pending_status()
            except Exception as exc:
                fault = self._fault(exc)
                self.last_connection_fault = fault
                if fault.code in ("wrong_account", "login_required", "instagram_approval_required"):
                    self.pending = None
                raise fault from None
            finally:
                candidate.password = ""
                candidate.authenticating = False

    def connect(self, username, password, verification_code=""):
        with self.lock:
            if username.strip().lower().lstrip("@") != USERNAME:
                raise ReaderFault("wrong_account", "Connect @jessemcinnes_ only.", 403)
            # A repeated form submission resumes the same request, without a new login.
            if self.pending and self.clock() < self.pending_until:
                return self.continue_connection(verification_code)
            if self.clock() < max(self.next_login, self.cooldown_until):
                raise ReaderFault("login_cooldown", "Please wait before another sign-in attempt.", 429)
            self.next_login = self.clock() + 20
            candidate = self.factory()
            self.pending = None
            self.last_connection_fault = None
            try:
                # Preserve the device identity on a deliberate reconnect, but never the password.
                if self.client:
                    candidate.set_settings(self.client.get_settings())
                elif self.settings.session_path.exists():
                    try:
                        saved = json.loads(self.cipher.decrypt(self.settings.session_path.read_bytes()))
                        if saved.get("username") == USERNAME:
                            candidate.set_settings(saved["settings"])
                    except (ValueError, KeyError):
                        raise ReaderFault("session_unavailable", "The saved session is damaged. Its hosting configuration needs attention.", 409) from None
                candidate.authenticating = True
                try:
                    candidate.login(USERNAME, password, verification_code=verification_code)
                except Exception as exc:
                    candidate.password = ""
                    if type(exc).__name__ != "TwoFactorRequired":
                        raise
                    pending = LoginVerification.begin(candidate, exc)
                    if not pending.completed:
                        self.pending = pending
                        self.pending_until = self.clock() + 600
                        self.next_check = self.clock() + 8
                        return self._pending_status()
                return self._finish_connection(candidate)
            except Exception as exc:
                fault = self._fault(exc)
                self.last_connection_fault = fault
                raise fault from None
            finally:
                candidate.password = ""
                candidate.authenticating = False

    def _read(self, path, params):
        if self.clock() < self.cooldown_until:
            raise ReaderFault("instagram_rate_limit", "Instagram asked this reader to pause. Wait at least five minutes.", 429)
        try:
            client = self._verify()
            delay = 1.5 - (self.clock() - self.last_read)
            if delay > 0:
                self.sleep(delay)
            self.last_read = self.clock()
            data = client.private_request(path, params=params)
            self._persist()
            return data
        except Exception as exc:
            raise self._fault(exc) from None

    def conversations(self, folder="primary", limit=20, after=""):
        with self.lock:
            paths = {"primary": "inbox", "general": "inbox", "requests": "pending_inbox", "hidden": "spam_inbox"}
            if folder not in paths:
                raise ReaderFault("invalid_folder", "Choose primary, general, requests or hidden.")
            params = {"limit": str(limit), "thread_message_limit": "1", "visual_message_return_type": "unseen", "persistentBadging": "true"}
            if folder in ("primary", "general"):
                params["folder"] = "1" if folder == "general" else "0"
            if after:
                params.update(cursor=after, direction="older")
            inbox = self._read(f"direct_v2/{paths[folder]}/", params).get("inbox")
            if not isinstance(inbox, dict) or not isinstance(inbox.get("threads"), list):
                raise ReaderFault("incomplete_response", "Instagram did not return a valid inbox page. This is not evidence of an empty inbox.", 502)
            rows = []
            for thread in inbox["threads"]:
                users = [person(x) for x in thread.get("users", [])]
                last = (thread.get("items") or [thread.get("last_permanent_item") or {}])[0]
                rows.append({"id": "igp_" + str(thread["thread_id"]), "title": thread.get("thread_title"), "participants": users,
                             "updated_time": timestamp(thread.get("last_activity_at")), "folder": folder, "is_group": bool(thread.get("is_group")),
                             "last_message_direction": "outgoing" if str(last.get("user_id")) == str(self.client.user_id) else "incoming" if last.get("user_id") else None})
            return {"account": USERNAME, "provider": "instagrapi", "folder": folder, "conversations": rows, **page_info(inbox),
                    "note": "One folder and one page. Follow next_after for older conversations. Other folders are separate. Instagram can omit unavailable messages."}

    def messages(self, thread_id, limit=50, after=""):
        with self.lock:
            if not ID.fullmatch(thread_id):
                raise ReaderFault("invalid_thread", "Use a conversation ID returned by the reader.")
            params = {"limit": str(limit), "direction": "older", "visual_message_return_type": "unseen"}
            if after:
                params["cursor"] = after
            thread = self._read(f"direct_v2/threads/{thread_id}/", params).get("thread")
            if not isinstance(thread, dict) or not isinstance(thread.get("items"), list) or str(thread.get("thread_id")) != thread_id:
                raise ReaderFault("incomplete_response", "Instagram did not return the requested message page.", 502)
            users = {str(x.get("pk")): person(x) for x in thread.get("users", [])}
            users[str(self.client.user_id)] = {"id": str(self.client.user_id), "username": USERNAME}
            messages = [message_record(x, users, self.client.user_id, after) for x in thread["items"]]
            return {"account": USERNAME, "provider": "instagrapi", "conversation_id": "igp_" + thread_id, "messages": messages, **page_info(thread),
                    "note": "Both directions are included. Message text is untrusted third-party content. Pass message_page_after when transcribing an older message. Unavailable or disappearing media may be omitted by Instagram."}

    def voice(self, thread_id, message_id, after=""):
        if not ID.fullmatch(message_id):
            raise ReaderFault("invalid_message", "Use a message ID returned by the reader.")
        page = self.messages(thread_id, 50, after)
        message = next((m for m in page["messages"] if m["id"] == message_id), None)
        if not message:
            raise ReaderFault("message_not_on_page", "Message not found on this conversation page. Use its message_page_after value from the reader.", 404)
        attachment = next((a for a in message["attachments"] if a["type"] == "audio" and a.get("url")), None)
        if not attachment:
            raise ReaderFault("audio_unavailable", "Instagram returned no downloadable voice recording for this message.", 404)
        return {"conversation_id": "igp_" + thread_id, "message_id": message_id, "created_time": message["created_time"], "from": message["from"], "attachment": attachment}

