"""Resume a server-issued Instagram verification flow without another login.

Only literal parameters for these fixed authentication actions are accepted.
Bloks expressions are parsed as data, never executed. Pending state stays in RAM.
"""
from dataclasses import dataclass
import json
import re

ENTRY = "com.bloks.www.two_step_verification.entrypoint"
APPROVAL = "com.bloks.www.two_step_verification.has_been_allowed.async"
VERIFY = "com.bloks.www.two_step_verification.verify_code.async"


class VerificationUnavailable(Exception):
    pass


def _map_items(client, expression):
    items = client._bloks_expression_items(expression)
    if len(items) != 3 or items[0] != "f4i":
        raise ValueError("Not a literal parameter map")
    keys = client._bloks_expression_items(items[1])
    values = client._bloks_expression_items(items[2])
    if keys[:1] != ["dkc"] or values[:1] != ["dkc"] or len(keys) != len(values):
        raise ValueError("Unpaired parameter map")
    result = {}
    for key, value in zip(keys[1:], values[1:]):
        name = json.loads(key)
        if not isinstance(name, str) or name in result:
            raise ValueError("Invalid parameter name")
        result[name] = value
    return result


def _literal(client, expression, depth=0):
    if depth > 8:
        raise ValueError("Parameter nesting limit")
    if expression.startswith("(f4i"):
        return {key: _literal(client, value, depth + 1) for key, value in _map_items(client, expression).items()}
    if expression.startswith("(dkc"):
        return [_literal(client, item, depth + 1) for item in client._bloks_expression_items(expression)[1:]]
    # json.loads rejects executable expressions and identifiers.
    return json.loads(expression)


def server_parameters(client, result, action):
    """Read the static map attached to this exact action, without guessing IDs."""
    strings = []
    client._bloks_collect_strings(result, strings)
    anchor = re.compile(re.escape(json.dumps(action)))
    next_action = re.compile(r"(?<![_a-zA-Z0-9])com\.bloks\.[_a-zA-Z0-9.]+")
    for text in strings:
        if len(text) > 2_000_000:
            continue
        for found in anchor.finditer(text):
            start = text.find("(f4i", found.end())
            other = next_action.search(text, found.end())
            if start < 0 or (other and other.start() < start):
                continue
            expression = client._bloks_parenthesized_expression(text, start)
            try:
                fields = _map_items(client, expression)
                # Client parameters can contain expressions; do not evaluate them.
                params = _literal(client, fields["server_params"]) if "server_params" in fields else _literal(client, expression)
                context = params.get("two_step_verification_context")
                if isinstance(context, str) and 0 < len(context) <= 32768:
                    return params
            except (ValueError, TypeError, KeyError, AttributeError):
                continue
    return None


@dataclass
class LoginVerification:
    client: object
    kind: str
    params: dict
    completed: bool = False

    @classmethod
    def begin(cls, client, error):
        sources = [getattr(error, "result", {}), getattr(client, "last_json", {})]
        params = next((p for source in sources if isinstance(source, dict) and (p := server_parameters(client, source, ENTRY))), None)
        context = params.get("two_step_verification_context") if params else getattr(error, "two_step_verification_context", "")
        if not context:
            context = next((c for source in sources if isinstance(source, dict) and (c := client.bloks_extract_two_step_verification_context(source))), "")
        if not isinstance(context, str) or not 0 < len(context) <= 32768:
            raise VerificationUnavailable()
        if params:
            result = client.bloks_app(ENTRY, {"client_input_params": {"device_id": client.android_device_id, "is_whatsapp_installed": 0, "machine_id": client.mid}, "server_params": params})
        else:
            result = client.bloks_two_step_verification_entrypoint(context)
        if client.bloks_apply_login_response(result):
            return cls(client, "complete", {}, True)
        approval = server_parameters(client, result, APPROVAL)
        if approval:
            return cls(client, "approval", approval)
        verify = server_parameters(client, result, VERIFY)
        if verify and verify.get("challenge") in ("totp", "sms", "backup_codes"):
            return cls(client, verify["challenge"], verify)
        # Never mislabel an unknown verification screen as an SMS/code request.
        raise VerificationUnavailable()

    def check(self, code=""):
        client = self.client
        inputs = {"auth_secure_device_id": "", "block_store_machine_id": "", "family_device_id": client.phone_id,
                  "should_trust_device": 1, "device_id": client.android_device_id, "cloud_trust_token": None,
                  "network_bssid": None, "machine_id": client.mid}
        action = APPROVAL if self.kind == "approval" else VERIFY
        if self.kind != "approval":
            inputs["code"] = code
        result = client.bloks_async_action(action, {"client_input_params": inputs, "server_params": self.params}, login=True)
        if client.bloks_apply_login_response(result):
            return True
        updated = server_parameters(client, result, action)
        if updated:
            self.params = updated
        return False

