import pytest

from bridge.cursors import valid_inbox_cursor


@pytest.mark.parametrize("value", [
    "", "older_page=", "12345",
    '{"cursor_thread_v2_id":1574920077232276,"cursor_relevancy_score":0,"cursor_timestamp_seconds":1770124582}',
])
def test_instagram_cursor_formats(value):
    assert valid_inbox_cursor(value)


@pytest.mark.parametrize("value", [
    "x" * 2001, "not a cursor", '{"url":"https://example.test"}',
    '{"cursor_thread_v2_id":true,"cursor_relevancy_score":0,"cursor_timestamp_seconds":1}',
    '{"cursor_thread_v2_id":{},"cursor_relevancy_score":0,"cursor_timestamp_seconds":1}',
    '{"cursor_thread_v2_id":1,"cursor_relevancy_score":0,"cursor_timestamp_seconds":-1}',
    '[]', '{"cursor_thread_v2_id":1}',
])
def test_invalid_cursor_formats(value):
    assert not valid_inbox_cursor(value)
